class CavaFinancialMode(str, Enum):
    INTEGRATED_TRANSACTIONAL_PROVIDER = \"INTEGRATED_TRANSACTIONAL_PROVIDER\"
    STANDALONE_MANUAL = \"STANDALONE_MANUAL\"


class CavaPaymentEvidenceKind(str, Enum):
    HOMOLOGATED_TRANSACTION = \"HOMOLOGATED_TRANSACTION\"
    MANUAL_AUDITED_ENTRY = \"MANUAL_AUDITED_ENTRY\"


@dataclass(frozen=True)
class CavaFinancialSourcePolicy:
    mode: CavaFinancialMode
    provider_reference: Optional[str] = None


@dataclass(frozen=True)
class CavaPaymentEvidence:
    evidence_kind: CavaPaymentEvidenceKind
    amount: float
    transaction_reference: Optional[str] = None
    source_system: Optional[str] = None
    source_unit_id: Optional[str] = None
    registered_by_user_id: Optional[str] = None
    audit_reference: Optional[str] = None


def validate_financial_source_policy(policy: CavaFinancialSourcePolicy) -> None:
    if policy.mode == CavaFinancialMode.INTEGRATED_TRANSACTIONAL_PROVIDER:
        if not str(policy.provider_reference or \"\").strip():
            raise ValueError(\"El modo integrado requiere provider_reference\")
        return
    if policy.mode == CavaFinancialMode.STANDALONE_MANUAL:
        if policy.provider_reference not in (None, \"\"):
            raise ValueError(\"STANDALONE_MANUAL no debe declarar proveedor transaccional integrado\")
        return
    raise ValueError(\"Modo financiero no soportado\")


def validate_payment_evidence(policy: CavaFinancialSourcePolicy, evidence: CavaPaymentEvidence) -> None:
    validate_financial_source_policy(policy)
    if float(evidence.amount) <= 0:
        raise ValueError(\"El importe del pago debe ser mayor que cero\")

    if policy.mode == CavaFinancialMode.INTEGRATED_TRANSACTIONAL_PROVIDER:
        if evidence.evidence_kind != CavaPaymentEvidenceKind.HOMOLOGATED_TRANSACTION:
            raise ValueError(\"Modo integrado no permite pagos manuales en Cavas\")
        for field_name, value in ((\"transaction_reference\", evidence.transaction_reference), (\"source_system\", evidence.source_system), (\"source_unit_id\", evidence.source_unit_id)):
            if not str(value or \"\").strip():
                raise ValueError(f\"Pago integrado requiere {field_name}\")
        return

    if evidence.evidence_kind != CavaPaymentEvidenceKind.MANUAL_AUDITED_ENTRY:
        raise ValueError(\"Standalone solo permite registro manual auditado\")
    for field_name, value in ((\"registered_by_user_id\", evidence.registered_by_user_id), (\"audit_reference\", evidence.audit_reference)):
        if not str(value or \"\").strip():
            raise ValueError(f\"Pago manual standalone requiere {field_name}\")


def manual_payment_allowed(policy: CavaFinancialSourcePolicy) -> bool:
    validate_financial_source_policy(policy)
    return policy.mode == CavaFinancialMode.STANDALONE_MANUAL
